        for(var p:List.of(i,d,source))for(String[] pair:new String[][]{{"tenant_id","tenant_id"},{"data_domain_id","data_domain_id"},{"execution_pool_id","execution_pool_id"},{"client_id","command_caller_client_id"},{"producer_deployment_id","producer_deployment_id"},{"admission_epoch","admission_epoch"},{"module_id","module_id"},{"migration_epoch","migration_epoch"},{"command_id","command_id"},{"expires_at","expires_at"}})check(same(p.get(pair[0]),r.get(pair[1])));
        for(var p:List.of(i,source))check(same(p.get("wire_payload"),r.get("command_wire_bytes"))&&same(p.get("wire_payload_hash"),r.get("command_wire_sha256")));
        check("R2B1_ENFORCED".equals(i.get("evidence_provenance"))&&"PROCESSED".equals(i.get("status"))&&"SENT".equals(i.get("result_status"))&&same(i.get("message_id"),r.get("source_message_id"))&&same(i.get("event_id"),r.get("source_event_id"))&&same(source.get("message_id"),r.get("source_message_id"))&&same(source.get("event_id"),r.get("source_event_id"))&&same(source.get("delivery_id"),r.get("delivery_id"))&&"PUBLISHED".equals(source.get("status")));
        for(String[] pair:new String[][]{{"runtime_binding_id","runtime_binding_id"},{"runtime_binding_generation","dispatch_binding_generation"},{"dispatch_runtime_instance_id","runtime_instance_id"},{"dispatch_runtime_credential_client_id","runtime_credential_client_id"},{"dispatch_receiver_registration_revision","receiver_registration_revision"},{"dispatch_generation_fact_id","dispatch_generation_fact_id"},{"dispatch_generation_snapshot_sha256","dispatch_generation_snapshot_sha256"}})check(same(i.get(pair[0]),r.get(pair[1])));
