            String type=text(fact,"fact_type");
            if(prior==null){check("START_GRANTED".equals(type)&&number(fact,"lease_revision")==0&&fact.get("previous_lease_fact_id")==null&&same(fact.get("holder_generation_fact_id"),r.get("dispatch_generation_fact_id"))&&same(fact.get("causing_receipt_id"),required(g.receipt("STARTED")).get("receipt_id")));}
