        // Exact projection provenance: transport+receipt increments on both sides; other lease facts only on inbox.
        long deliveryVersion=Math.addExact(number(i,"claim_delivery_version"),1L+g.receipts().size());long extra=g.facts().stream().filter(f->!Set.of("START_GRANTED","SETTLED").contains(f.get("fact_type"))).count();
