    private Map<String,Object> holder(Object id,Object hash,Map<Object,Map<String,Object>> index){
        var f=index.computeIfAbsent(id,key->{var rows=store.jdbc().queryForList("SELECT * FROM agent_runtime_v2_binding_generation_fact WHERE binding_generation_fact_id=?",key);check(rows.size()==1);var fact=rows.getFirst();var rs=store.jdbc().queryForList("SELECT * FROM agent_runtime_v2_registration_receipt WHERE registration_receipt_id=?",fact.get("registration_receipt_id"));check(rs.size()==1);AgentRuntimeV2RegistrationServiceImpl.validateReceipt(rs.getFirst());AgentRuntimeV2RegistrationServiceImpl.validateHolder(fact,rs.getFirst());return fact;});
        check(same(f.get("generation_snapshot_sha256"),hash));return f;
    }
    private void holderLink(Map<String,Object> row,String prefix,Map<String,Object> original,Map<Object,Map<String,Object>> index){var f=holder(row.get(prefix+"_generation_fact_id"),row.get(prefix+"_generation_snapshot_sha256"),index);String generation=prefix.equals("ack_holder")?"ack_holder_binding_generation":prefix.equals("requested_holder")?"requested_holder_binding_generation":"holder_binding_generation";check(same(row.get(generation),f.get("binding_generation")));for(String n:List.of("runtime_binding_id","runtime_instance_id","registration_subject_sha256","registration_authority_id","process_public_key_sha256","tenant_id","data_domain_id","execution_pool_id","runtime_credential_client_id","owner_jiacn","agent_id","claimant_deployment_id","claimant_worker_generation","admission_epoch","module_id","migration_epoch"))check(same(f.get(n),original.get(n)));check(number(f,"receiver_registration_revision")>=number(original,"receiver_registration_revision")&&number(f,"registration_authority_revision")>=number(original,"registration_authority_revision"));}
    public static void origin(Map<String,Object> value,AgentRuntimeV2InternalOutboxRow r){check("R2B1_ENFORCED".equals(value.get("evidence_provenance"))&&same(value.get("execution_origin_snapshot_sha256"),r.get("execution_origin_snapshot_sha256")));for(String[] pair:new String[][]{{"runtime_dispatch_id","runtime_dispatch_id"},{"runtime_binding_id","runtime_binding_id"},{"runtime_instance_id","runtime_instance_id"},{"tenant_id","tenant_id"},{"data_domain_id","data_domain_id"},{"execution_pool_id","execution_pool_id"},{"client_id","command_caller_client_id"},{"runtime_credential_client_id","runtime_credential_client_id"},{"owner_jiacn","owner_jiacn"},{"agent_id","agent_id"},{"producer_deployment_id","producer_deployment_id"},{"claimant_deployment_id","claimant_deployment_id"},{"claimant_worker_generation","claimant_worker_generation"},{"receiver_registration_revision","receiver_registration_revision"},{"admission_epoch","admission_epoch"},{"module_id","module_id"},{"migration_epoch","migration_epoch"}}){if(!value.containsKey(pair[0]))check(Set.of("runtime_binding_id","runtime_instance_id").contains(pair[0])&&value.containsKey("created_at")&&value.containsKey("execution_grant_id")&&!value.containsKey("grant_wire_bytes"));else check(same(value.get(pair[0]),r.get(pair[1])));}if(value.containsKey("dispatch_binding_generation"))check(same(value.get("dispatch_binding_generation"),r.get("dispatch_binding_generation")));if(value.containsKey("inbox_id"))check(same(value.get("inbox_id"),r.get("inbox_id"))&&same(value.get("delivery_id"),r.get("delivery_id")));}
